import { tables, mysql } from "@aicore-fivem/mysql";
import type { TableInserts, Tables } from "./tables";

/** ai-exitsleeping's tables, typed from sql/main.sql (`tables.ts` is generated by the build). */
export const db = tables<Tables, TableInserts>();

type Row = Tables["ai_exitsleeping_sleepers"];
export type StoredSleeper = Omit<Row, "logged_out_at"> & {
  /** Seconds since the logout (computed in SQL, so the server's time zone never matters). */
  age: number;
};

const LOAD_CHUNK = 5000;
const PURGE_CHUNK = 5000;
const SAVE_CHUNK = 500;

/** Deletes bodies older than `days`, a chunk per statement so a big purge never holds long locks. */
export async function purgeOlderThan(days: number): Promise<number> {
  let total = 0;
  for (;;) {
    const affected =
      (await mysql.update(
        "DELETE FROM ai_exitsleeping_sleepers WHERE logged_out_at < UTC_TIMESTAMP() - INTERVAL ? DAY LIMIT ?",
        [days, PURGE_CHUNK],
      )) ?? 0;
    total += affected;
    if (affected < PURGE_CHUNK) return total;
  }
}

/** Every stored body, read in primary key chunks (keyset, never OFFSET). */
export async function loadAll(each: (row: StoredSleeper) => void) {
  let after = 0;
  for (;;) {
    const rows = await mysql.query<StoredSleeper[]>(
      `SELECT char_id, model, anim, x, y, z, heading,
              TIMESTAMPDIFF(SECOND, logged_out_at, UTC_TIMESTAMP()) AS age
       FROM ai_exitsleeping_sleepers WHERE char_id > ? ORDER BY char_id LIMIT ?`,
      [after, LOAD_CHUNK],
    );
    for (const row of rows) each(row);
    const last = rows[rows.length - 1];
    if (!last || rows.length < LOAD_CHUNK) return;
    after = last.char_id;
  }
}

/** A new body (a second logout of the same character replaces the old row and restarts its age). */
export function insertSleeper(s: Omit<Row, "logged_out_at">) {
  return mysql.query(
    `INSERT INTO ai_exitsleeping_sleepers (char_id, model, anim, x, y, z, heading, logged_out_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, UTC_TIMESTAMP())
     ON DUPLICATE KEY UPDATE model = VALUES(model), anim = VALUES(anim), x = VALUES(x), y = VALUES(y),
       z = VALUES(z), heading = VALUES(heading), logged_out_at = VALUES(logged_out_at)`,
    [s.char_id, s.model, s.anim, s.x, s.y, s.z, s.heading],
  );
}

export function deleteSleeper(charId: number) {
  return db.remove("ai_exitsleeping_sleepers", { char_id: charId });
}

/** Positions of moved bodies: one `UPDATE ... JOIN` per 500 rows. */
export async function savePositions(
  list: Array<Pick<Row, "char_id" | "x" | "y" | "z" | "heading">>,
) {
  for (let i = 0; i < list.length; i += SAVE_CHUNK) {
    const part = list.slice(i, i + SAVE_CHUNK);
    const rows = part
      .map((_, n) =>
        n === 0
          ? "SELECT ? AS id, ? AS x, ? AS y, ? AS z, ? AS h"
          : "SELECT ?, ?, ?, ?, ?",
      )
      .join(" UNION ALL ");
    await mysql.query(
      `UPDATE ai_exitsleeping_sleepers s JOIN (${rows}) v ON s.char_id = v.id
       SET s.x = v.x, s.y = v.y, s.z = v.z, s.heading = v.h`,
      part.flatMap((p) => [p.char_id, p.x, p.y, p.z, p.heading]),
    );
  }
}
